document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("paint-form"),n=document.getElementById("paint-result");e&&e.addEventListener("submit",function(e){e.preventDefault();const t=parseFloat(document.getElementById("paint-wall-area").value),a=parseFloat(document.getElementById("paint-doors").value),s=parseFloat(document.getElementById("paint-windows").value),o=parseFloat(document.getElementById("paint-additional").value),r=parseFloat(document.getElementById("paint-surface-type").value),l=parseFloat(document.getElementById("paint-quality").value),p=parseFloat(document.getElementById("paint-coats").value),i="true"===document.getElementById("paint-primer").value;if(t<=0)return n.textContent="Please enter a valid wall area.",void 0;const d=21*a,u=15*s,c=t-d-u,m=c+o;if(m<=0)return n.textContent="Total area to paint must be positive. Check your measurements.",void 0;const g=l*r,$=m*p,f=$/g,v=Math.ceil(4*f)/4;let h=0,y=0;if(i){h=m/(250*r),y=Math.ceil(4*h)/4}const E=v+.1*v,q=Math.ceil(4*E)/4,w=25*v,B=80*v,P=20*y,b=50*y,I=Math.round(v%1*4),M=Math.floor(v),C=Math.round(y%1*4),F=Math.floor(y);n.innerHTML=`\n        <div class="result-section">\n          <h4>Area Calculations:</h4>\n          <p>Total wall area: ${t} sq ft</p>\n          <p>Less doors: ${d} sq ft (${a} doors)</p>\n          <p>Less windows: ${u} sq ft (${s} windows)</p>\n          <p>Net paintable area: ${c} sq ft</p>\n          ${o>0?`<p>Additional area: ${o} sq ft</p>`:""}\n          <p><strong>Total area to paint: ${m} sq ft</strong></p>\n          <p><strong>Paint needed for ${p} coat${p>1?"s":""}: ${$} sq ft coverage</strong></p>\n        </div>\n        \n        <div class="result-paint">\n          <h4>Paint Requirements:</h4>\n          <p><strong>${v} gallons of paint</strong></p>\n          <p>(${M} gallons${I>0?` + ${I} quarts`:""})</p>\n          <p>Effective coverage: ${g} sq ft/gallon</p>\n          ${i?`\n          <p><strong>${y} gallons of primer</strong></p>\n          <p>(${F} gallons${C>0?` + ${C} quarts`:""})</p>\n          `:""}\n        </div>\n        \n        <div class="result-recommendations">\n          <h4>Purchase Recommendations:</h4>\n          <p><strong>Buy: ${q} gallons of paint</strong> <em>(includes 10% extra)</em></p>\n          ${i?`<p><strong>Buy: ${y} gallons of primer</strong></p>`:""}\n          <p>💡 Always buy extra for touch-ups and color matching</p>\n          <p>🎨 Purchase all paint from the same batch for color consistency</p>\n        </div>\n        \n        <div class="result-costs">\n          <h4>Estimated Costs:</h4>\n          <p>Paint: $${w}-$${B} (${v} gallons)</p>\n          ${i?`<p>Primer: $${P}-$${b} (${y} gallons)</p>`:""}\n          <p><em>Prices vary by brand, quality, and retailer</em></p>\n        </div>\n        \n        <div class="result-supplies">\n          <h4>Additional Supplies Needed:</h4>\n          <p>🖌️ Brushes (2-3 different sizes)</p>\n          <p>🎢 Rollers and roller covers</p>\n          <p>📋 Paint trays and liners</p>\n          <p>🛡️ Drop cloths and plastic sheeting</p>\n          <p>📏 Painter's tape</p>\n          <p>🧽 Cleaning supplies</p>\n        </div>\n        \n        <div class="result-tips">\n          <p><em>🏠 Consider hiring professionals for high ceilings or complex projects</em></p>\n          <p><em>🌡️ Paint in temperatures between 50-85°F for best results</em></p>\n          <p><em>⏰ Allow proper drying time between coats (2-4 hours typical)</em></p>\n        </div>\n      `})});